import{d as h,C as i,o as g,c as u,j as n,a as e,E as o,a3 as d}from"./chunks/framework.Q4yG9rk_.js";const y=JSON.parse('{"title":"中庸·第8章","description":"《中庸》第 8 章——颜回之为人：择乎中庸，得一善则拳拳服膺而弗失。能择能守的样子。","frontmatter":{"title":"中庸·第8章","description":"《中庸》第 8 章——颜回之为人：择乎中庸，得一善则拳拳服膺而弗失。能择能守的样子。","category":"guide","aliases":["第8章","中庸第8章","拳拳服膺"],"source":["《礼记》","《四书章句集注》"],"outline":[2,3]},"headers":[],"relativePath":"lizhimingde/sishu-wujing/zhongyong/chapter-08.md","filePath":"lizhimingde/sishu-wujing/zhongyong/chapter-08.md","lastUpdated":1790316338000}'),m={name:"lizhimingde/sishu-wujing/zhongyong/chapter-08.md"},b=h({...m,setup(p){const t=[{id:"ze",label:"回之为人也 · 择乎中庸",showLabel:!0,sentences:[["子曰：“",{text:"回",glossary:"hui"},"之为人也，",{text:"择乎中庸",glossary:"zehu"},"，"]],note:"孔子举颜回：「回之为人也，择乎中庸」——颜回为人，选定了中庸之道。与上章那些「择而不能守」的人恰好相对。"},{id:"shou",label:"得一善 · 拳拳服膺而弗失",showLabel:!0,sentences:[["得一善，则",{text:"拳拳",glossary:"quanquan"},{text:"服膺",glossary:"fuying"},"而",{text:"弗失",glossary:"fushi"},"之矣。”"]],note:"「得一善，则拳拳服膺而弗失之矣」——得到一个善，就紧紧握持在心（拳拳＝牢握不舍；服膺＝放在心上），再不丢失。这正是颜回能「守」的实证。"}],r=[{id:"hui",term:"回",pinyin:"huí",meaning:"颜回，字子渊，孔子弟子。朱注以为此篇以知、仁、勇三达德为入道之门，舜（知）、颜渊（仁）、子路（勇）各当其一，此章正举「仁」。"},{id:"zehu",term:"择乎中庸",pinyin:"zé hū zhōng yōng",meaning:"择取中庸之道。与上章「择乎中庸而不能期月守」正成对照。"},{id:"quanquan",term:"拳拳",pinyin:"quán quán",meaning:"奉持不舍的样子。朱注：「拳拳，奉持之貌。」"},{id:"fuying",term:"服膺",pinyin:"fú yīng",meaning:"服：著（附着）；膺：胸。著之于心胸之间，即记在心上、持而不忘。"},{id:"fushi",term:"弗失",pinyin:"fú shī",meaning:"不失掉。朱注：「奉持而著之心胸之间，言能守也。」"}];return(c,a)=>{const s=i("DaoTextReading"),l=i("DaoKeywordCards");return g(),u("div",null,[a[0]||(a[0]=n("h1",{id:"中庸·第8章",tabindex:"-1"},[e("中庸·第8章 "),n("a",{class:"header-anchor",href:"#中庸·第8章","aria-label":'Permalink to "中庸·第8章"'},"​")],-1)),a[1]||(a[1]=n("h2",{id:"【原典层】原文",tabindex:"-1"},[e("【原典层】原文 "),n("a",{class:"header-anchor",href:"#【原典层】原文","aria-label":'Permalink to "【原典层】原文"'},"​")],-1)),a[2]||(a[2]=n("p",null,[e("本章举颜回，正与上章相对：上章说「择而不能守」，颜回是"),n("strong",null,"能择又能守"),e("——「得一善，则拳拳服膺而弗失之」。默认竹简沉浸通读；切「经典阅读」可点生词。")],-1)),o(s,{colophon:"择乎中庸 · 拳拳服膺",tone:"ink",sections:t,glossary:r,"default-mode":"slips","aria-label":"中庸·第8章 原文"}),a[3]||(a[3]=n("h2",{id:"【原典层】注音与字词",tabindex:"-1"},[e("【原典层】注音与字词 "),n("a",{class:"header-anchor",href:"#【原典层】注音与字词","aria-label":'Permalink to "【原典层】注音与字词"'},"​")],-1)),o(l,{items:[{term:"回",pinyin:["huí"],meaning:"颜回，字子渊，孔子弟子，以仁著称。"},{term:"择乎中庸",pinyin:["zé","hū","zhōng","yōng"],meaning:"择取中庸之道。与上章「择而不能守」正成对照。"},{term:"拳拳",pinyin:["quán","quán"],meaning:"奉持不舍的样子。朱注：「拳拳，奉持之貌。」"},{term:"服膺",pinyin:["fú","yīng"],meaning:"服：著；膺：胸。著之胸中，即记在心上、持而不忘。"},{term:"弗失",pinyin:["fú","shī"],meaning:"不失掉。朱注：「奉持而著之心胸之间，言能守也。」"}]}),a[4]||(a[4]=d('<p>全篇生词的完整释义在<a href="/Dao/reference/glossary/">字词释义字典</a>中统一维护。</p><h2 id="【原典层】白话译文" tabindex="-1">【原典层】白话译文 <a class="header-anchor" href="#【原典层】白话译文" aria-label="Permalink to &quot;【原典层】白话译文&quot;">​</a></h2><p><strong>回之为人也 · 择乎中庸</strong>：颜回的为人，择取中庸之道。</p><p><strong>得一善 · 拳拳服膺而弗失</strong>：得到一善，就紧紧奉持、记在心上，不使它失掉。</p><h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一篇在说什么" tabindex="-1">象：这一篇在说什么 <a class="header-anchor" href="#象-这一篇在说什么" aria-label="Permalink to &quot;象：这一篇在说什么&quot;">​</a></h3><p>第八章只有两句，说的是颜回：<strong>择乎中庸</strong>、<strong>得一善则拳拳服膺而弗失</strong>。上章刚说「能择而不能守」，这一章就给出能择能守的样子。朱注：「颜子盖真知之，故能择能守如此。」</p><h3 id="理-为什么值得读" tabindex="-1">理：为什么值得读 <a class="header-anchor" href="#理-为什么值得读" aria-label="Permalink to &quot;理：为什么值得读&quot;">​</a></h3><ul><li><strong>它的功夫落在「一善」上</strong>：不是得一箩筐道理，而是<strong>得一善即守之</strong>。少而能守，胜过多而皆失。</li><li><strong>「服膺」是身体化的持守</strong>：朱注解为「奉持而著之心胸之间」——不是记住一个结论，而是把它放到心上、日日对着。</li><li><strong>「弗失」定出了标准</strong>：守的判准不是「知道过」，而是「没有丢」。</li><li><strong>它与前两章连成一组</strong>：第六章舜（知）能择能用；第七章众人择而不能守；第八章颜回（仁）能择能守。三章之间的落差，正是全篇的关切——<strong>同一个「择」，后面接的是「守不守得住」</strong>。</li></ul><h3 id="用-今日可用之处" tabindex="-1">用：今日可用之处 <a class="header-anchor" href="#用-今日可用之处" aria-label="Permalink to &quot;用：今日可用之处&quot;">​</a></h3><ol><li><strong>得一善</strong>：不贪多——今天只挑一条真正受用的，守住它。</li><li><strong>服膺</strong>：把它写下来、放在每天看得见的地方（不是收藏，是常对着）。</li><li><strong>用「弗失」自检</strong>：上周或上个月的那一善，还在吗？</li></ol><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>颜回这个人，选择了中庸；而且<strong>得到一善，就紧紧捧着放在心口，不让它丢掉</strong>。</p><p>这一章最动人的地方是「一善」两个字：不是懂得很多，而是守住一个。上章说多数人「择而不能守」，颜回给出的答案是——<strong>少取一点，守在心上，不失掉。</strong></p><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><blockquote><p>待补——这一节留给自己的读后想法。</p></blockquote><p>可以按这几条慢慢写：</p><ul><li>「得一善」——如果只能从我最近学的道理里留下一善，我留哪一条？</li><li>「服膺」——我是把它放进了笔记，还是放进了生活？（「记住」与「对着」的区别）</li><li>「弗失」——过去一年我真正没有丢掉的，是哪一条？</li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/Dao/lizhimingde/sishu-wujing/zhongyong/">中庸总览</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/">四书五经总览</a></li><li>同栏目：<a href="/Dao/lizhimingde/sishu-wujing/daxue/">大学</a> · <a href="/Dao/lizhimingde/sishu-wujing/lunyu/">论语</a> · <a href="/Dao/lizhimingde/sishu-wujing/mengzi/">孟子</a></li><li>上章：<a href="/Dao/lizhimingde/sishu-wujing/zhongyong/chapter-07">中庸·第7章</a>　下章：<a href="/Dao/lizhimingde/sishu-wujing/zhongyong/chapter-09">中庸·第9章</a></li><li>参考：《礼记》第三十一篇；朱熹《四书章句集注·中庸章句》</li></ul>',20))])}}});export{y as __pageData,b as default};
